import { ReplyQuote, Card } from "march/ui"

// günün sözü: alıntı bloğu, mor çubuk, tek satıra kısaltılmaz
export function QuoteOfTheDay() {
  return <Card m:theme="night">
    <ReplyQuote name="Yunus Emre" text="Gelin tanış olalım, işi kolay kılalım." lines={0} m:color="brand-purple" />
  </Card>
}

import { ReplyQuote, TextInput, Button } from "march/ui"

// mesaj yazarken yanıt: alanın üstünde vazgeç düğmeli önizleme
export function ComposerReply() {
  let $reply = true
  return <div sx={{ flex: "col", gap: 2 }}>
    {() => ($reply ? <ReplyQuote name="Deniz Kaya'ya yanıt" text="Cumartesi sabahı sahil koşusu için buluşma yerini değiştirdik." lines={1}
      onClose={() => $reply = false} closeLabel="Yanıttan vazgeç" /> : <Button size="sm" on:click={() => $reply = true}>Yanıtla</Button>)}
    <TextInput aria-label="Mesaj" placeholder="Mesaj yaz…" />
  </div>
}

import { ReplyQuote, Button } from "march/ui"
import { trash } from "march/icons"

// ReplyQuote'un özellikleri: name, text, lines, variant, bar, onClose, close (kendi ikonun), closeLabel, trail,
// onClick, class
export function ReplyQuoteLab() {
  let $log = "—"
  return <div sx={{ flex: "col", gap: 2 }}>
    <ReplyQuote class="lab-q" name="Elif" text="Uzun bir mesaj metni" lines={2} variant="soft" bar={false}
      onClose={() => $log = "vazgeçildi"} close={trash} closeLabel="Kaldır" trail={<Button size="sm">Git</Button>} onClick={() => $log = "tıklandı"} />
    <span class="lab-log">{$log}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ReplyQuoteLab } from "./ReplyQuoteLab.tsx"

// ReplyQuoteLab'in testleri: kaydedince Testler sekmesinde çalışır
test("ad ve metin çizilir", () => {
  const s = renderTest(() => <ReplyQuoteLab />)
  expect(s.get(".lab-q")?.textContent).toContain("Elif")
  expect(s.get(".lab-q")?.textContent).toContain("Uzun bir mesaj metni")
})

test("kapat düğmesi closeLabel adıyla onClose'u çağırır", async () => {
  const s = renderTest(() => <ReplyQuoteLab />)
  await s.click("Kaldır")
  expect(s.get(".lab-log")?.textContent).toBe("vazgeçildi")
})
